# THE HEADER HANDLING IS TRANSCRIBED from the code version's executor, case for case, because the
# details are what make a real sheet usable:
#
#   a blank header cell    becomes Column1, Column2, … by POSITION, so a gap in the header row does not
#                          collapse two columns into one key
#   a short row            missing cells become null rather than being absent, so every row has the
#                          same keys and a downstream template can rely on them
#   headers with one row   `useHeaders` needs at least a header AND a data row; with only a header the
#                          code version fell through to raw arrays, and so does this
#
# `total` is the count of DATA rows, which is why it is read off the mapped result rather than off
# `values` — with headers on, the header row is not a row of data.

- emit: rows
  value: |
    return (() => {
      const values = response.values || [];
      if (!config.useHeaders || values.length <= 1) return values;
      const headers = (values[0] || []).map((h, i) => h ? String(h) : 'Column' + (i + 1));
      return values.slice(1).map(row =>
        Object.fromEntries(headers.map((h, i) => [h, row[i] !== undefined ? row[i] : null]))
      );
    })();

- emit: total
  value: |
    return (() => {
      const values = response.values || [];
      if (!config.useHeaders || values.length <= 1) return values.length;
      return values.length - 1;
    })();
